class Solution:
    def minimumTime(self, jobs: List[int], workers: List[int]) -> int:
        jobs.sort()
        workers.sort()
        return max((j + w - 1) // w for j, w in zip(jobs, workers))

c.cpp:
class Solution {
public:
    long long minimumTime(vector<int>& jobs, vector<int>& workers) {
        sort(jobs.begin(), jobs.end());
        sort(workers.begin(), workers.end());
        long long ans = 0;
        for (int i = 0; i < (int)jobs.size(); ++i)
            ans = max(ans, (long long)(jobs[i] + workers[i] - 1) / workers[i]);
        return ans;
    }
};

c.java:
class Solution {
    public long minimumTime(int[] jobs, int[] workers) {
        Arrays.sort(jobs);
        Arrays.sort(workers);
        long ans = 0;
        for (int i = 0; i < jobs.length; i++)
            ans = Math.max(ans, (jobs[i] + workers[i] - 1L) / workers[i]);
        return ans;
    }
}

c.javascript:
var minimumTime = function(jobs, workers) {
    jobs.sort((a, b) => a - b);
    workers.sort((a, b) => a - b);
    let ans = 0;
    for (let i = 0; i < jobs.length; i++)
        ans = Math.max(ans, Math.ceil(jobs[i] / workers[i]));
    return ans;
};
